import{_ as i,o,c as a,aa as n}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/en/diary/en_m_popis_cisla.jpg",s="/buildary-help-preview/media/cs/diary/m_ikona_poznamky_1.png",l="/buildary-help-preview/media/cs/diary/m_ikona_poznamky_2.png",d="/buildary-help-preview/media/en/diary/en_m_menu_vlevo.jpg",c="/buildary-help-preview/media/en/diary/en_m_menu_vpravo.jpg",h="/buildary-help-preview/media/en/diary/en_m_menudne.jpg",p="/buildary-help-preview/media/en/diary/en_m_stav_dne.jpg",g="/buildary-help-preview/media/en/diary/btn_pocasi.png",e="/buildary-help-preview/media/en/diary/btn_pridat.png",u="/buildary-help-preview/media/en/diary/en_m_dz_menu.jpg",D=JSON.parse('{"title":"Daily Records","description":"","frontmatter":{"title":"Daily Records","wiki":"en:diary:m_dailyentries"},"headers":[],"relativePath":"en/diary/m_dailyentries.md","filePath":"en/diary/m_dailyentries.md","lastUpdated":1794388980000}'),y={name:"en/diary/m_dailyentries.md"};function m(f,t,b,w,v,_){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="daily-records" tabindex="-1">Daily Records <a class="header-anchor" href="#daily-records" aria-label="Permalink to &quot;Daily Records&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A detailed description of Daily Records is provided in the <a href="/buildary-help-preview/en/diary/dailyentries">Daily Records</a> chapter. This section describes only how to work with Daily Records in the mobile app.</p></div><h2 id="description-of-the-daily-records-screen-in-the-mobile-app" tabindex="-1">Description of the Daily Records Screen in the Mobile App <a class="header-anchor" href="#description-of-the-daily-records-screen-in-the-mobile-app" aria-label="Permalink to &quot;Description of the Daily Records Screen in the Mobile App&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+r+'" alt="" width="250" loading="lazy"></figure><p>The Daily Records screen is divided into five parts:</p><ol><li><strong>Control Panel</strong> contains, from left to right:</li></ol><ul><li>App menu</li><li>Abbreviated name of the current diary</li><li>Context menu related to the specific day and its current status.</li></ul><ol start="2"><li><strong>Date Panel</strong> displays the selected day and arrows for moving one day backward or forward. Tapping the panel opens a calendar for directly selecting a day. A colored bar below the panel indicates the status of the day.<br><strong>Day Note</strong> (public/private)</li><li><strong>Current Section</strong> panel with its name, section note, and a magnifying glass for searching within the section. Notes are not available for the Performed Works and Additional Records sections.</li><li>Area for the <strong>actual Daily Records</strong> of the selected section.</li><li><strong>Daily Records Sections</strong> → you can switch between individual sections either by tapping the section name or by swiping sideways.</li></ol><figure class="shot" style="--w:35px;"><img src="'+s+'" alt="" width="30" loading="lazy"></figure><figure class="shot" style="--w:35px;"><img src="'+l+'" alt="" width="30" loading="lazy"></figure><p><strong>Day Note:</strong></p><p>A public and/or private note can be added to each day. A public note is visible to all users who have access to the diary, while a private note is visible only to the user who created it.</p><p>The icon for adding and viewing a note is located in the Date Panel (2.).</p><p>Icon with an &quot;empty&quot; speech bubble = no note has been entered</p><p>Icon with a &quot;filled&quot; (white) speech bubble = a note has been entered</p><h2 id="description-of-available-menu-options" tabindex="-1">Description of Available Menu Options <a class="header-anchor" href="#description-of-available-menu-options" aria-label="Permalink to &quot;Description of Available Menu Options&quot;">​</a></h2><h3 id="app-menu" tabindex="-1">App Menu <a class="header-anchor" href="#app-menu" aria-label="Permalink to &quot;App Menu&quot;">​</a></h3><img src="'+d+'" alt="" width="250" loading="lazy"><p>The app menu is available by tapping the icon with three horizontal lines on the left side of the Control Panel. At the top, the menu displays the abbreviated name of the current project, the diary number and full diary name, and the user&#39;s account name. Below this is the main menu:</p><ul><li><strong>Diary History</strong> – displays the history of visited diaries. Below the list, the <strong>Go to Project List</strong> button allows you to select another project.</li><li><strong>Diary List</strong> – displays the list of diaries for the currently open project.</li><li><strong>Diary Documents</strong> – provides access to the Documents section of the diary&#39;s Identification Details.</li><li><strong>Work Offline / Work Online</strong> – switches the app to offline mode, i.e. without an Internet connection, or back to online mode.</li><li><strong>Settings</strong> – takes you to Signature Settings.</li><li><strong>Feedback</strong> – allows you to send us a form, for example with suggestions for improving the app.</li><li><strong>Help</strong> – online help for the Buildary.online application.</li><li><strong>Log Out</strong> – logs the user out after confirmation.</li></ul><h3 id="day-context-menu" tabindex="-1">Day Context Menu <a class="header-anchor" href="#day-context-menu" aria-label="Permalink to &quot;Day Context Menu&quot;">​</a></h3><img src="'+c+'" alt="" width="250" loading="lazy"><p>The context menu is available by tapping the vertical three-dot icon on the right side of the Control Panel.</p><figure class="shot" style="--w:300px;"><img src="'+h+'" alt="" width="250" loading="lazy"></figure><ul><li><strong>Download Day as PDF</strong> – downloads the Daily Report for the currently displayed day.</li><li><strong>Sign Day OR Download for Electronic Signature</strong> and <strong>Upload Electronically Signed File</strong> – allows you to electronically sign and lock the day according to the configured signature method, either directly in the Buildary app or using an external application. Once signed, the day can no longer be unlocked by a user.</li><li><strong>Copy Entire Day</strong> – first displays a calendar for selecting the source day from which data should be copied, followed by a window where you can select sections and filter records by author.</li><li><strong>User Lock Day / Cancel User Lock</strong> – locks (or unlocks) the day with its current contents, meaning that records can no longer be added or edited for that day.</li><li><strong>Non-Working Day / Working Day</strong> – marks the day as non-working or working. <strong>WARNING! Marking a day as non-working will delete all records for that day, if any exist!</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The menu always displays only the options that are applicable to the current status of the day.</p></div><h2 id="day-status" tabindex="-1">Day Status <a class="header-anchor" href="#day-status" aria-label="Permalink to &quot;Day Status&quot;">​</a></h2><img src="'+p+'" alt="" width="250" loading="lazy"><p>A colored bar below the calendar panel indicates the status of the selected day:</p><ul><li><strong>Red</strong> – the day contains no data.</li><li><strong>Blue</strong> – the day contains data and is not locked.</li><li><strong>Yellow</strong> – the day is in the process of being signed and is temporarily locked against modifications. This status is time-limited. After signing, it changes to <strong>green</strong>, or, once the configured time limit expires, it returns to <strong>blue</strong> (or <strong>purple</strong>).</li><li><strong>Purple</strong> – the day is user-locked and can be unlocked at any time.</li><li><strong>Green</strong> – the day has been electronically signed and is therefore locked against any further changes. It can no longer be unlocked by a user.</li><li><strong>Gray</strong> – non-working day. The day contains no data and is locked. It can be unlocked as long as no signed day exists after it.</li></ul><h2 id="weather-section" tabindex="-1">Weather Section <a class="header-anchor" href="#weather-section" aria-label="Permalink to &quot;Weather Section&quot;">​</a></h2><p>Tapping the cloud icon <img src="'+g+'" alt="" width="25" loading="lazy"> loads weather data from the Internet (the project must be located on the map).</p><p>The loaded values can be manually edited by tapping the relevant row.</p><p>A note concerning weather phenomena can be added to the weather data.</p><p>All loaded values can be deleted at once by tapping the trash icon in the section panel.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The time at which the weather data is loaded from the server is not important. The server uses either already measured values from weather stations or a forecast, depending on what is available.</p></div><h2 id="persons-on-site-machinery-materials-products-and-technological-supplies-sections" tabindex="-1">Persons on Site / Machinery / Materials, Products and Technological Supplies Sections <a class="header-anchor" href="#persons-on-site-machinery-materials-products-and-technological-supplies-sections" aria-label="Permalink to &quot;Persons on Site / Machinery / Materials, Products and Technological Supplies Sections&quot;">​</a></h2><p>Records are added using the entry form displayed after tapping the <img src="'+e+'" alt="" width="25" loading="lazy"> button.</p><p>To change or edit a record, briefly tap the record. It will open in an editing window where you can modify it.</p><p>Pressing and holding a record activates the bulk deletion function. You can then select the desired records using the checkboxes and tap the trash icon in the section panel to delete the selected records.</p><p>A note concerning the relevant section can also be added to each section.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When entering records, suggestions from previously saved items are available. Only items from the current diary and section are offered.</p></div><h2 id="performed-works-section" tabindex="-1">Performed Works Section <a class="header-anchor" href="#performed-works-section" aria-label="Permalink to &quot;Performed Works Section&quot;">​</a></h2><p>Records are added using the entry form displayed after tapping the <img src="'+e+'" alt="" width="25" loading="lazy"> button.</p><p>When entering a record in this section, as with Additional Records, the following options are available:</p><ul><li>Use AI to describe the record (from photos)</li><li>Add details to the record using markers on a drawing (if drawings have been uploaded in the project settings and this field is set to <strong>Displayed</strong> in the diary settings)</li><li>Locate the record on the map (if this field is set to <strong>Displayed</strong> in the diary settings), either manually or by using the device&#39;s current location</li><li>Launch the camera to take photos or record video for the record</li><li>Select and attach a file from the device&#39;s storage</li></ul><p>The size of an individual uploaded document must not exceed 30 MB.</p><p>To change or edit a record, briefly tap the record. It will open in an editing window where you can modify it.</p><h2 id="additional-records-section" tabindex="-1">Additional Records Section <a class="header-anchor" href="#additional-records-section" aria-label="Permalink to &quot;Additional Records Section&quot;">​</a></h2><p>Records are added using the entry form displayed after tapping the <img src="'+e+'" alt="" width="25" loading="lazy"> button.</p><p>When entering a record in this section, as with Performed Works, the following options are available:</p><ul><li>Use AI to describe the record (from photos)</li><li>Add details to the record using markers on a drawing (if drawings have been uploaded in the project settings and this field is set to <strong>Displayed</strong> in the diary settings)</li><li>Locate the record on the map (if this field is set to <strong>Displayed</strong> in the diary settings), either manually or by using the device&#39;s current location</li><li>Launch the camera to take photos or record video for the record</li><li>Select and attach a file from the device&#39;s storage</li></ul><p>The size of an individual uploaded document must not exceed 30 MB.</p><p>To change or edit a record, briefly tap the record. It will open in an editing window where you can modify it.</p><p>Additional Records also have their <strong>own context menu</strong> in the upper-right corner of each record, containing the following options:</p><figure class="shot" style="--w:250px;"><img src="'+u+'" alt="" width="200" loading="lazy"></figure><ul><li><strong>Download for Viewing</strong> – generates a PDF file of the record and opens it in the selected application.</li><li><strong>Upload Scan of This Record</strong> – by selecting a scanned, signed record (report) in PDF or JPEG format, the document is uploaded to the record and the record is locked without using an electronic signature.</li><li><strong>Sign Record</strong> (OR <strong>Download for Electronic Signature / Upload Electronically Signed File</strong>) – signs the record according to the signature method selected for the user account.</li><li><strong>Message Recipient List</strong> – displays a list of Authorized Persons for the diary, with the option to manually send an email notification about the selected record.</li><li><strong>Respond to This Record</strong> – allows you to add a response to the selected record, linking it to the record&#39;s discussion thread.</li><li><strong>Related Records</strong> – displays the record thread, i.e. the original record and all related responses. Each newly created independent record forms a new thread.</li><li><strong>Delete</strong> – allows you to delete the record. This option is not available for signed records.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>In the <strong>Additional Records</strong> section, each user <strong>signs their own records</strong>. This is a necessary step for successfully signing the day.</p></div>',58)])])}const P=i(y,[["render",m]]);export{D as __pageData,P as default};
